using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments = new()
    {
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" }
    };

    private readonly List<Course> _courses = new()
    {
        new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a renowned researcher in algorithm optimization. He previously worked at Google Research and holds multiple patents in distributed computing.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Principles of database design, relational algebra, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez specializes in large-scale data management. She has contributed to several open-source database projects and consults for Fortune 500 companies.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Hughes", InstructorBio = "Dr. Hughes is a mathematician with a passion for teaching. He has won multiple teaching excellence awards and authored two widely-used calculus textbooks.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson bridges pure mathematics and applied data science. Her research focuses on matrix computations and their applications in AI.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, CourseCode = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Turing Jr.", InstructorBio = "Dr. Turing Jr. is an expert in statistical modeling with applications to biomedical research. He leads the university's statistical consulting center.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 7, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Lab Fri 1:00–3:00 PM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura is an experimental physicist whose research explores quantum mechanics at the nanoscale. She is passionate about hands-on physics education.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 202", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Tue 3:00–5:00 PM", InstructorName = "Dr. Kevin O'Brien", InstructorBio = "Dr. O'Brien has conducted research at CERN and specializes in electromagnetic theory and its applications in modern technology.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 9, CourseCode = "ENG 101", Title = "English Composition", Description = "Develops college-level writing skills through essays, research papers, and critical analysis of texts.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Diana Reeves", InstructorBio = "Prof. Reeves is a published author and writing coach with 20 years of experience helping students find their voice through writing.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson is a literary scholar specializing in 20th-century American fiction. He has published three books on the Harlem Renaissance.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 11, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural developments, and global interactions from prehistory to 1500 CE.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Fatima Al-Rashid", InstructorBio = "Dr. Al-Rashid is an archaeologist and historian who has led excavations across the Middle East and North Africa. She brings artifacts and primary sources into the classroom.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 12, CourseCode = "HIST 205", Title = "Modern European History", Description = "Europe from the French Revolution to the present: industrialization, nationalism, world wars, and European integration.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Heinrich Müller", InstructorBio = "Dr. Müller is a specialist in modern European political history. He has served as a visiting professor at universities in Berlin, Paris, and London.", DepartmentId = 5, IsFeatured = true }
    };

    private readonly List<EnrollmentRequest> _enrollments = new();

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

